#include <Arduino.h>
#include <string.h>

char command[16];
unsigned int length = 0;
bool overflowed = false;
unsigned long lastByte = 0;

void finishCommand() {
  command[length] = '\0';
  if (!overflowed) {
    if (strcmp(command, "ON") == 0) digitalWrite(13, HIGH);
    else if (strcmp(command, "OFF") == 0) digitalWrite(13, LOW);
  }
  length = 0;
  overflowed = false;
}

void setup() {
  pinMode(13, OUTPUT);
  digitalWrite(13, LOW);
  Serial.begin(9600);
}

void loop() {
  while (Serial.available() > 0) {
    char c = (char)Serial.read();
    lastByte = millis();
    if (c == '\n' || c == '\r') {
      finishCommand();
    } else if (length < sizeof(command) - 1) {
      command[length++] = c;
    } else {
      overflowed = true;
    }
  }
  if ((length > 0 || overflowed) && (unsigned long)(millis() - lastByte) >= 20) {
    finishCommand();
  }
}
